import { Hono } from 'hono';
import { zValidator } from '../../common/validate.js';
import { requirePermission } from '../../common/auth.js';
import { leaveController } from './leave.controller.js';
import { createLeaveRequestSchema, createLeaveTypeSchema, decideLeaveRequestSchema } from './leave.schema.js';
export const leaveRoutes = new Hono();
leaveRoutes.get('/types', requirePermission('leave.view'), leaveController.listTypes);
leaveRoutes.post('/types', requirePermission('leave.manage'), zValidator('json', createLeaveTypeSchema), leaveController.createType);
leaveRoutes.get('/', requirePermission('leave.view'), leaveController.list);
leaveRoutes.get('/staff/:staffId', requirePermission('leave.view'), leaveController.listByStaff);
leaveRoutes.get('/staff/:staffId/balance', requirePermission('leave.view'), leaveController.balance);
leaveRoutes.get('/:id', requirePermission('leave.view'), leaveController.getById);
leaveRoutes.post('/', requirePermission('leave.manage'), zValidator('json', createLeaveRequestSchema), leaveController.apply);
leaveRoutes.post('/:id/approve', requirePermission('leave.approve'), zValidator('json', decideLeaveRequestSchema), leaveController.approve);
leaveRoutes.post('/:id/reject', requirePermission('leave.approve'), zValidator('json', decideLeaveRequestSchema), leaveController.reject);
